// @FIGURE_CODE_BEGIN
var FIGW = 960, FIGH = 600;
var svg = SVG().addTo(document.getElementById('container')).size('100%', '100%');
svg.viewbox(0, 0, FIGW, FIGH).attr('preserveAspectRatio', 'xMidYMid meet');

var RC = 165;                 // radius (px) representing one critical mass
var LAMBDA = 1.6 * RC;        // neutron mean free path (material constant, px)
var COL_SPHERE = '#8289c4';
var COL_ARROW = '#111111';
var COL_STAR = '#ffc84d';
var COL_ESC = '#c0392b';
var COL_CAP = '#1e8449';
var FONT = 'Helvetica Neue, Helvetica, Arial, sans-serif';

var CY_ESC = 522, CY_CAP = 541, CY_K = 560, CY_LAB = 586;

var state = { mass: 1.0, view: 'Side by side', bump: 0 };
var timers = [], allEls = [], panelsData = [], glowGrad = null, neuGrad = null, marked = false;

/* ---------- utilities ---------- */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function distBoundary(px, py, dx, dy, R) {
  var b = px * dx + py * dy, c = px * px + py * py - R * R;
  var disc = b * b - c;
  if (disc < 0) return 0;
  return Math.max(0, -b + Math.sqrt(disc));
}
function minDistTo(x, y, sites) {
  var m = 1e9;
  for (var i = 0; i < sites.length; i++) {
    var d = Math.hypot(sites[i].x - x, sites[i].y - y);
    if (d < m) m = d;
  }
  return m;
}
function clearTimers() { for (var i = 0; i < timers.length; i++) clearTimeout(timers[i]); timers = []; }
function txt(parent, str, x, y, size, weight, fill, italic) {
  var t = parent.text(str);
  t.font({ family: FONT, size: size, weight: weight || 'normal', anchor: 'middle', style: italic ? 'italic' : 'normal' });
  t.fill(fill || '#1a1a1a');
  t.center(x, y);
  return t;
}
function titleFor(m) {
  if (m < 0.95) return 'Sub-critical mass';
  if (m <= 1.12) return 'Critical mass';
  return 'Super-critical mass';
}
function verdict(k) {
  if (k < 0.95) return '— chain dies out';
  if (k <= 1.12) return '— self-sustaining';
  return '— grows each generation';
}

/* ---------- chain-reaction simulation ---------- */
function simulate(cx, cy, R, seed) {
  var rnd = mulberry32(seed);
  var maxSites = Math.max(6, Math.min(28, Math.round(20 * Math.pow(R / RC, 2))));
  var maxGen = 7;
  var sites = [], arrows = [], queue = [];
  var emitByGen = [];

  var first = { x: cx - 0.34 * R, y: cy - 0.28 * R, g: 0, rot: rnd() * 3 };
  sites.push(first); queue.push(first);

  while (queue.length && sites.length < maxSites) {
    var s = queue.shift();
    if (s.g >= maxGen) continue;
    emitByGen[s.g] = (emitByGen[s.g] || 0) + 1;
    var n = (rnd() < 0.45) ? 2 : 3;
    var base = rnd() * 6.2832;
    for (var i = 0; i < n; i++) {
      var ang = base + i * 6.2832 / n + (rnd() - 0.5) * 0.8;
      var dx = Math.cos(ang), dy = Math.sin(ang);
      var L = distBoundary(s.x - cx, s.y - cy, dx, dy, R);
      var pcap = 1 - Math.exp(-L / LAMBDA);
      if (rnd() < pcap) {
        var px = 0, py = 0, tries = 0, a2 = ang;
        while (tries < 6) {
          a2 = ang + (tries ? (rnd() - 0.5) * 1.4 : 0);
          var cxd = Math.cos(a2), cyd = Math.sin(a2);
          var L2 = distBoundary(s.x - cx, s.y - cy, cxd, cyd, R);
          var t2 = Math.min(L2 * 0.62, 40 + rnd() * 36);
          if (t2 < 26) t2 = Math.min(L2 * 0.85, 26);
          px = s.x + cxd * t2; py = s.y + cyd * t2;
          if (minDistTo(px, py, sites) > 27) break;
          tries++;
        }
        var child = { x: px, y: py, g: s.g + 1, rot: rnd() * 3 };
        sites.push(child); queue.push(child);
        arrows.push({ x1: s.x, y1: s.y, x2: px, y2: py, gen: s.g, fate: 'captured' });
      } else {
        arrows.push({
          x1: s.x, y1: s.y,
          x2: s.x + dx * (L + 17), y2: s.y + dy * (L + 17),
          gen: s.g, fate: 'escaped'
        });
      }
    }
  }
  return { sites: sites, arrows: arrows, emitByGen: emitByGen, maxSites: maxSites };
}

/* ---------- drawing primitives ---------- */
function drawArrow(g, x1, y1, x2, y2, tipTrim) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
  if (len < 4) return null;
  var ux = dx / len, uy = dy / len;
  var sx = x1 + ux * 13, sy = y1 + uy * 13;
  var ex = x2 - ux * tipTrim, ey = y2 - uy * tipTrim;
  var l2 = Math.hypot(ex - sx, ey - sy);
  if (l2 < 10) { sx = x1 + ux * 6; sy = y1 + uy * 6; l2 = Math.hypot(ex - sx, ey - sy); }
  if (l2 < 8) return null;
  var hl = Math.min(16, l2 * 0.5), hw = 11.5;
  var bx = ex - ux * hl, by = ey - uy * hl;
  var grp = g.group();
  grp.line(sx, sy, bx + ux * 1.5, by + uy * 1.5).stroke({ color: COL_ARROW, width: 4.2, linecap: 'butt' });
  grp.polygon([[ex, ey], [bx - uy * hw / 2, by + ux * hw / 2], [bx + uy * hw / 2, by - ux * hw / 2]]).fill(COL_ARROW);
  var hit = grp.line(sx, sy, ex, ey).stroke({ color: '#ffffff', width: 17, opacity: 0 });
  hit.css('cursor', 'pointer');
  return { group: grp, hit: hit };
}

function drawStar(g, x, y, r, rot) {
  var st = g.group();
  st.circle(r * 3.1).center(x, y).fill(glowGrad);
  var pts = [], N = 13;
  for (var i = 0; i < 2 * N; i++) {
    var a = rot + i * Math.PI / N;
    var rr = (i % 2) ? r * 0.34 : r * (0.84 + 0.28 * (((i * 7) % 5) / 5));
    pts.push([x + rr * Math.cos(a), y + rr * Math.sin(a)]);
  }
  st.polygon(pts).fill(COL_STAR);
  st.circle(r * 0.85).center(x, y).fill('#fff8dc');
  var hit = st.circle(r * 1.9).center(x, y).fill('#ffffff').opacity(0);
  hit.css('cursor', 'pointer');
  return { group: st, hit: hit };
}

/* ---------- panel ---------- */
function drawPanel(cfg) {
  var R = RC * Math.pow(cfg.m, 0.72);
  var cx = cfg.cx, cy = cfg.cy;

  /* pick a seed that yields a reasonably populated cascade (visual only) */
  var sim = null, bestSim = null;
  for (var attempt = 0; attempt < 8; attempt++) {
    var s = simulate(cx, cy, R, cfg.seed + attempt * 131 + state.bump * 7717);
    if (!bestSim || s.sites.length > bestSim.sites.length) bestSim = s;
    if (s.sites.length >= Math.min(5, s.maxSites)) { sim = s; break; }
  }
  if (!sim) sim = bestSim;

  var gBack = svg.group();
  var circ = gBack.circle(2 * R).center(cx, cy).fill(COL_SPHERE);
  circ.css('cursor', 'pointer');

  /* faint dashed radius */
  var ra = 0.95;
  var rex = cx + R * Math.cos(ra), rey = cy + R * Math.sin(ra);
  gBack.line(cx, cy, rex, rey).stroke({ color: '#ffffff', width: 1.6, dasharray: '6,5', opacity: 0.55 });
  var rl = txt(gBack, 'r', cx + R * 0.55 * Math.cos(ra) + 11, cy + R * 0.55 * Math.sin(ra) - 8, 14, 'bold', '#ffffff', true);
  rl.attr({ 'paint-order': 'stroke', stroke: '#6b71ad', 'stroke-width': 2.6, 'stroke-linejoin': 'round' });

  /* title / panel label */
  txt(svg, cfg.title, cx, 24, 19, 'bold', '#141414');
  txt(svg, cfg.label, cx, CY_LAB, 15, 'normal', '#141414');

  /* arrows (below stars) */
  var gArrows = svg.group();
  for (var i = 0; i < sim.arrows.length; i++) {
    var a = sim.arrows[i];
    var ar = drawArrow(gArrows, a.x1, a.y1, a.x2, a.y2, a.fate === 'captured' ? 16 : 0);
    if (!ar) continue;
    (function (a, ar) {
      var tip = (a.fate === 'escaped')
        ? 'Neutron ESCAPED through the surface — lost from the chain'
        : 'Neutron CAPTURED — caused another fission (arrowhead lands on the new starburst)';
      ar.hit.on('mousemove', function (e) { showTooltip(tip, e); })
        .on('mouseleave', function () { hideTooltip(); })
        .on('click', function () {
          if (a.fate === 'escaped') showPopup('Escaped neutron', 'This neutron reached the surface before striking a nucleus, so it leaves the sphere and is lost from the chain. Small spheres have a large surface-to-volume ratio, so most neutrons end this way.');
          else showPopup('Captured neutron', 'This neutron was absorbed by another nucleus and triggered a new fission. When the captures per fission reach one (k = 1), every fission replaces itself and the chain sustains.');
        });
    })(a, ar);
    allEls.push({ el: ar.group, reveal: a.gen + 1 });
  }

  /* starbursts (on top) */
  var gStars = svg.group();
  for (var j = 0; j < sim.sites.length; j++) {
    var st = sim.sites[j];
    var sg = drawStar(gStars, st.x, st.y, 15, st.rot);
    (function (st, sg) {
      sg.hit.on('mousemove', function (e) { showTooltip('Fission event — generation ' + st.g + ' (releases 2–3 fast neutrons)', e); })
        .on('mouseleave', function () { hideTooltip(); })
        .on('click', function () { showPopup('Fission event', 'A neutron struck a fissile nucleus and split it, releasing energy plus 2–3 fast neutrons. Each of those neutrons either finds another nucleus (the chain continues) or reaches the surface and leaves.'); });
    })(st, sg);
    allEls.push({ el: sg.group, reveal: st.g });
  }

  /* initiating neutron + its arrow */
  var nx = cx - 0.848 * (R + 48), ny = cy - 0.53 * (R + 48);
  var gInit = svg.group();
  var ia = drawArrow(gInit, nx, ny, sim.sites[0].x, sim.sites[0].y, 16);
  var gNeu = svg.group();
  var neu = gNeu.circle(23).center(nx, ny).fill(neuGrad);
  neu.css('cursor', 'pointer');
  neu.on('mousemove', function (e) { showTooltip('Initiating neutron arriving from outside', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Initiating neutron', 'A single stray neutron enters the sample and causes the first fission. Whether that one event grows into a chain depends entirely on how many of the neutrons it releases are captured rather than lost.'); });
  if (ia) allEls.push({ el: ia.group, reveal: 0 });
  allEls.push({ el: gNeu, reveal: 0 });

  /* per-generation tallies */
  var maxR = 0;
  sim.arrows.forEach(function (a) { if (a.gen + 1 > maxR) maxR = a.gen + 1; });
  var escA = [], capA = [], emitA = [];
  for (var r = 0; r <= maxR; r++) { escA[r] = 0; capA[r] = 0; emitA[r] = 0; }
  sim.arrows.forEach(function (a) {
    if (a.fate === 'escaped') escA[a.gen + 1]++; else capA[a.gen + 1]++;
  });
  for (var g2 = 0; g2 < sim.emitByGen.length; g2++) {
    if (sim.emitByGen[g2] && g2 + 1 <= maxR) emitA[g2 + 1] += sim.emitByGen[g2];
  }

  var pd = {
    cx: cx, R: R, m: cfg.m, label: cfg.label, maxR: maxR,
    escA: escA, capA: capA, emitA: emitA,
    tEsc: txt(svg, '', cx, CY_ESC, 12.5, 'bold', COL_ESC),
    tCap: txt(svg, '', cx, CY_CAP, 12.5, 'bold', COL_CAP),
    tK: txt(svg, '', cx, CY_K, 12.5, 'bold', '#333')
  };
  panelsData.push(pd);

  circ.on('mousemove', function (e) {
    showTooltip('Fissile sphere ' + cfg.label + ': mass = ' + cfg.m.toFixed(2) + ' × critical, radius r = ' + Math.round(R) + ' px', e);
  }).on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Why size decides it', 'Neutrons are lost only through the surface (∝ r²) but can be captured anywhere in the volume (∝ r³). Growing the sphere raises the capture chance faster than the escape chance, so past the critical radius each fission replaces itself and the chain sustains.');
    });
  return pd;
}

/* ---------- counters ---------- */
function fatesUpTo(pd, r) {
  var lim = Math.min((r === Infinity ? pd.maxR : r), pd.maxR);
  var e = 0, c = 0, m = 0;
  for (var i = 0; i <= lim; i++) { e += pd.escA[i]; c += pd.capA[i]; m += pd.emitA[i]; }
  return { e: e, c: c, em: m };
}
function updateCounters(pd, r) {
  var f = fatesUpTo(pd, r), tot = f.e + f.c;
  var pe = tot ? Math.round(100 * f.e / tot) : 0;
  pd.tEsc.text('neutrons escaped: ' + f.e + ' / ' + tot + (tot ? '  (' + pe + '%)' : ''));
  pd.tEsc.center(pd.cx, CY_ESC);
  pd.tCap.text('captured → fission: ' + f.c + ' / ' + tot + (tot ? '  (' + (100 - pe) + '%)' : ''));
  pd.tCap.center(pd.cx, CY_CAP);
  var k = f.em ? f.c / f.em : 0;
  pd.tK.text('k ≈ ' + k.toFixed(2) + '  ' + verdict(k));
  pd.tK.fill(k < 0.95 ? COL_ESC : (k <= 1.12 ? '#1a5fb4' : '#b35c00'));
  pd.tK.center(pd.cx, CY_K);
  pd.kNow = k; pd.escNow = f.e; pd.capNow = f.c;
}
function updateReadout() {
  var html = '';
  for (var i = 0; i < panelsData.length; i++) {
    var p = panelsData[i];
    var tot = p.escNow + p.capNow;
    html += '<b>' + p.label + '</b> m = ' + p.m.toFixed(2) + ' × crit, r = ' + Math.round(p.R) +
      ' → escape ' + (tot ? Math.round(100 * p.escNow / tot) : 0) + '%, <b>k ≈ ' + p.kNow.toFixed(2) + '</b><br>';
  }
  document.getElementById('kReadout').innerHTML = html;
}

/* ---------- legend ---------- */
function drawLegend() {
  var g = svg.group();
  drawStar(g, 24, 24, 9, 0.4);
  var t1 = g.text('fission event').font({ family: FONT, size: 11.5, anchor: 'start' }).fill('#333');
  t1.center(40 + t1.bbox().width / 2, 24);
  drawArrow(g, 8, 50, 40, 50, 0);
  var t2 = g.text('neutron').font({ family: FONT, size: 11.5, anchor: 'start' }).fill('#333');
  t2.center(46 + t2.bbox().width / 2, 50);
  g.circle(17).center(24, 74).fill(neuGrad);
  var t3 = g.text('initiating neutron').font({ family: FONT, size: 11.5, anchor: 'start' }).fill('#333');
  t3.center(40 + t3.bbox().width / 2, 74);
}

/* ---------- render ---------- */
function panelConfigs() {
  if (state.view === 'Side by side') {
    return [
      { title: 'Sub-critical mass', label: '(a)', cx: 236, cy: 268, m: 0.5, seed: 7 },
      { title: titleFor(state.mass), label: '(b)', cx: 688, cy: 268, m: state.mass, seed: 21 }
    ];
  }
  if (state.view === 'Sub-critical (a)') {
    return [{ title: 'Sub-critical mass', label: '(a)', cx: 480, cy: 272, m: 0.5, seed: 7 }];
  }
  return [{ title: titleFor(state.mass), label: '(b)', cx: 480, cy: 272, m: state.mass, seed: 21 }];
}

function render(doAnimate) {
  clearTimers();
  hideTooltip();
  svg.clear();
  allEls = []; panelsData = [];
  svg.rect(FIGW, FIGH).fill('#ffffff');

  glowGrad = svg.gradient('radial', function (add) {
    add.stop(0, '#fff8db', 0.95); add.stop(0.45, '#ffdf8c', 0.5); add.stop(1, '#ffd35c', 0);
  });
  neuGrad = svg.gradient('radial', function (add) {
    add.stop(0, '#f4f6e8'); add.stop(1, '#a2a888');
  });
  neuGrad.attr({ fx: 0.35, fy: 0.3 });

  var cfgs = panelConfigs();
  for (var i = 0; i < cfgs.length; i++) drawPanel(cfgs[i]);
  drawLegend();

  if (doAnimate) {
    for (var e = 0; e < allEls.length; e++) allEls[e].el.attr('opacity', 0);
    for (var p = 0; p < panelsData.length; p++) updateCounters(panelsData[p], -1);
    var maxR = 0;
    allEls.forEach(function (o) { if (o.reveal > maxR) maxR = o.reveal; });
    (function (maxR) {
      for (var r = 0; r <= maxR; r++) {
        (function (rr) {
          timers.push(setTimeout(function () {
            allEls.forEach(function (o) { if (o.reveal === rr) o.el.animate(320).attr({ opacity: 1 }); });
            panelsData.forEach(function (pd) { updateCounters(pd, rr); });
            updateReadout();
          }, 150 + rr * 620));
        })(r);
      }
    })(maxR);
  } else {
    for (var q = 0; q < allEls.length; q++) allEls[q].el.attr('opacity', 1);
    for (var s = 0; s < panelsData.length; s++) updateCounters(panelsData[s], Infinity);
  }
  updateReadout();

  if (!marked) { marked = true; window.__markRendered(); }
}

/* ---------- control handlers ---------- */
function update_massSlider(v) { state.mass = v; render(false); }
function toggle_panelView(v) { state.view = v; render(false); }
function trigger_chainReaction() { render(true); }
function trigger_newCascade() { state.bump = Math.floor(Math.random() * 9999); render(false); }

/* ---------- demo step player ---------- */
var steps = [
  {
    title: 'Two spheres, one difference',
    text: 'Two spheres of the same fissile material differ only in size. The small one is sub-critical; the large one is at critical mass. Watch what happens to the neutrons in each.',
    view: 'Side by side', mass: 1.0, play: false
  },
  {
    title: 'Neutrons leak out of a small sphere',
    text: 'In the sub-critical sphere, a single incoming neutron starts a few fissions, but most emitted neutrons reach the surface and escape before hitting another nucleus. The cascade fizzles out (k < 1).',
    view: 'Sub-critical (a)', mass: 0.5, play: true
  },
  {
    title: 'Neutrons stay home in a large sphere',
    text: 'In the critical sphere, the same single neutron starts a cascade that multiplies 1 → 2 → 4 → 8, because each emitted neutron finds another nucleus before reaching the surface. Only a few arrows escape at the edge.',
    view: 'Critical (b)', mass: 1.0, play: true
  },
  {
    title: 'Sweep the mass through the threshold',
    text: 'Drag the mass slider and watch the escape fraction fall as the radius grows. Around one critical mass the counters cross: captures per fission reach one, and the reaction becomes self-sustaining.',
    view: 'Critical (b)', mass: 1.0, play: false
  },
  {
    title: 'Beyond critical',
    text: 'Push past the critical mass and nearly every neutron is captured; each generation is larger than the last and the reaction grows explosively.',
    view: 'Critical (b)', mass: 1.5, play: true
  }
];
var curStep = 0;

function setStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[curStep];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.text;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + steps.length;
  var mi = document.getElementById('massSliderInput');
  mi.value = s.mass;
  document.getElementById('massSliderVal').value = (+s.mass).toFixed(2);
  document.getElementById('panelViewInput').value = s.view;
  state.mass = +s.mass;
  state.view = s.view;
  render(s.play);
}
function nextStep() { setStep(curStep + 1); }
function prevStep() { setStep(curStep - 1); }

setStep(0);
